// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

import {IDeploymentBlock} from "./interfaces/decent/IDeploymentBlock.sol";
import {
    Initializable
} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title DeploymentBlockInitializable
 * @author Decent Labs
 * @notice Abstract implementation of deployment block tracking for initializable contracts
 * @dev This abstract contract implements IDeploymentBlock, providing a standard
 * way to record when initializable contracts are deployed.
 *
 * Implementation details:
 * - Uses EIP-7201 namespaced storage pattern for upgradeability
 * - Records block number during initialization
 * - Deployment block is immutable once set
 * - Designed for UUPS and transparent proxy patterns
 * - Must be inherited by initializable contracts
 *
 * Usage:
 * - Call __DeploymentBlockInitializable_init() in the inheriting contract's initializer
 * - The deployment block is automatically set to the current block
 * - Query deploymentBlock() to get the recorded value
 *
 * Security considerations:
 * - Can only be set once during initialization
 * - Prevents reinitialization attacks
 * - Provides reliable deployment block number
 *
 * @custom:security-contact security@decentlabs.io
 */
abstract contract DeploymentBlockInitializable is
    Initializable,
    IDeploymentBlock
{
    // ======================================================================
    // STATE VARIABLES
    // ======================================================================

    /**
     * @notice Main storage struct for DeploymentBlockInitializable following EIP-7201
     * @dev Stores the block number when the contract was deployed
     * @custom:storage-location erc7201:Decent.DeploymentBlockInitializable.main
     */
    struct DeploymentBlockInitializableStorage {
        /** @notice The block number when this contract was deployed */
        uint256 deploymentBlock;
    }

    /**
     * @dev Storage slot for DeploymentBlockInitializableStorage calculated using EIP-7201 formula:
     * keccak256(abi.encode(uint256(keccak256("Decent.DeploymentBlockInitializable.main")) - 1)) & ~bytes32(uint256(0xff))
     */
    bytes32 internal constant DEPLOYMENT_BLOCK_INITIALIZABLE_STORAGE_LOCATION =
        0x8a73f35b9df1b6f9967ddd5a4ec6ec57f8bdee83334d4552823c6e36f981ab00;

    /**
     * @dev Returns the storage struct for DeploymentBlockInitializable
     * Following the EIP-7201 namespaced storage pattern to avoid storage collisions
     * @return $ The storage struct for DeploymentBlockInitializable
     */
    function _getDeploymentBlockInitializableStorage()
        internal
        pure
        returns (DeploymentBlockInitializableStorage storage $)
    {
        // solhint-disable-next-line no-inline-assembly
        assembly {
            $.slot := DEPLOYMENT_BLOCK_INITIALIZABLE_STORAGE_LOCATION
        }
    }

    // ======================================================================
    // CONSTRUCTOR & INITIALIZERS
    // ======================================================================

    /**
     * @notice Initializes the deployment block tracking
     * @dev Must be called by inheriting contracts in their initializer.
     * Records the current block number as the deployment block.
     * Can only be called once due to the check for existing value.
     * @custom:throws DeploymentBlockAlreadySet if already initialized
     */
    function __DeploymentBlockInitializable_init() internal onlyInitializing {
        // solhint-disable-previous-line func-name-mixedcase
        DeploymentBlockInitializableStorage
            storage $ = _getDeploymentBlockInitializableStorage();
        if ($.deploymentBlock != 0) {
            revert DeploymentBlockAlreadySet();
        }

        $.deploymentBlock = block.number;
    }

    // ======================================================================
    // IDeploymentBlock
    // ======================================================================

    // --- View Functions ---

    /**
     * @inheritdoc IDeploymentBlock
     */
    function deploymentBlock() public view virtual override returns (uint256) {
        DeploymentBlockInitializableStorage
            storage $ = _getDeploymentBlockInitializableStorage();
        return $.deploymentBlock;
    }
}

contracts/InitializerEventEmitter.sol.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

import {
    Initializable
} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title InitializerEventEmitter
 * @author Decent Labs
 * @notice Abstract contract for emitting initialization data during contract deployment
 * @dev This abstract contract provides a standardized way to emit initialization
 * data for initializable contracts in the Decent ecosystem.
 *
 * Implementation details:
 * - Designed to be inherited by upgradeable contracts
 * - Emits raw initialization data for transparency and auditability
 * - Minimal gas overhead with single event emission
 * - Follows OpenZeppelin's initializer pattern
 * - Uses `onlyInitializing` modifier for security
 *
 * Usage:
 * - Inherit this contract in your upgradeable contract
 * - Call `__InitializerEventEmitter_init()` in your initializer function
 * - Pass the encoded initialization parameters as bytes
 *
 * Example:
 * ```solidity
 * contract MyContract is InitializerEventEmitter, OtherContracts {
 *     function initialize(address owner_, uint256 value_) public initializer {
 *         bytes memory initData = abi.encode(owner_, value_);
 *         __InitializerEventEmitter_init(initData);
 *         // ... rest of initialization
 *     }
 * }
 * ```
 *
 * @custom:security-contact security@decentlabs.io
 */
abstract contract InitializerEventEmitter is Initializable {
    // ======================================================================
    // ERRORS
    // ======================================================================

    /**
     * @notice Thrown when attempting to initialize after already initialized
     * @dev Prevents reinitialization attacks on upgradeable contracts
     */
    error InitializeDataAlreadyEmitted();

    // ======================================================================
    // EVENTS
    // ======================================================================

    /**
     * @notice Emitted when a contract is initialized with data
     * @dev This event provides transparency for all initialization parameters
     * @param initData The raw initialization data passed to the contract
     */
    event InitializeData(bytes initData);

    // ======================================================================
    // STATE VARIABLES
    // ======================================================================

    /**
     * @notice Storage struct for InitializerEventEmitter following EIP-7201
     * @dev Tracks whether initialization data has been emitted
     * @custom:storage-location erc7201:Decent.InitializerEventEmitter.main
     */
    struct InitializerEventEmitterStorage {
        /** @notice Whether the initialization data has been emitted */
        bool initialized;
    }

    /**
     * @dev Storage slot for InitializerEventEmitterStorage calculated using EIP-7201 formula:
     * keccak256(abi.encode(uint256(keccak256("Decent.InitializerEventEmitter.main")) - 1)) & ~bytes32(uint256(0xff))
     */
    bytes32 internal constant INITIALIZER_EVENT_EMITTER_STORAGE_LOCATION =
        0xf7464a9b8e299d18ec8976df251e878e5204887b642c36b9e3e606b459323300;

    /**
     * @dev Returns the storage struct for InitializerEventEmitter
     * Following the EIP-7201 namespaced storage pattern to avoid storage collisions
     * @return $ The storage struct for InitializerEventEmitter
     */
    function _getInitializerEventEmitterStorage()
        internal
        pure
        returns (InitializerEventEmitterStorage storage $)
    {
        // solhint-disable-next-line no-inline-assembly
        assembly {
            $.slot := INITIALIZER_EVENT_EMITTER_STORAGE_LOCATION
        }
    }

    // ======================================================================
    // INITIALIZERS
    // ======================================================================

    /**
     * @notice Initializes the event emitter and emits the initialization data
     * @dev Must be called by inheriting contracts in their initializer function.
     * Can only be called once - subsequent calls will revert.
     * @param initData The initialization data to emit
     * @custom:throws InitializeDataAlreadyEmitted if already initialized
     */
    function __InitializerEventEmitter_init(
        // solhint-disable-previous-line func-name-mixedcase
        bytes memory initData
    ) internal onlyInitializing {
        InitializerEventEmitterStorage
            storage $ = _getInitializerEventEmitterStorage();

        if ($.initialized) {
            revert InitializeDataAlreadyEmitted();
        }

        $.initialized = true;
        emit InitializeData(initData);
    }
}

